\draw (-1.1,-1.2)--(-1.1,2.1);\draw (0,0) circle(1.1);\fill (0,0) circle(.025);
\draw[->,thick] (0,0)--(-1.1,1.9) node[above left] {$\vec T$};
\draw[->,thick] (0,0)--(0,1.8) node[right] {$\vec F_A$};
\draw[->,thick] (0,0)--(0,-1.7) node[right] {$m\vec g$};
